-- Command governance and Channel tables, owned by this chain.
--
-- Until now their DDL lived in the Enterprise tenant chain (packages/enterprise,
-- 0000_tenant_baseline and 0001_tenant_custom), generated by re-homing these models
-- into a placeholder schema. Installations that ran that chain already hold exactly
-- these tables, so this migration is written for both starting points and is
-- hand-written (drizzle-kit generate --custom); its snapshot is the schema diff
-- drizzle-kit generated for the same models:
--   * none of the tables exists: create them, with the DDL drizzle-kit generated for
--     the models plus what the models cannot express (foreign keys to "users", the
--     Channel revision functions and triggers);
--   * all of them exist: nothing is created or altered, whoever created them;
--   * only some exist: refuse, it is not a state any chain produced.
-- Either way the result is compared with the definition below (column names, types,
-- nullability and defaults, plus the primary key, unique, foreign key and check
-- constraints, indexes and triggers by name, and the trigger functions by body) and
-- the migration fails when a table differs, so a divergent table is found here and
-- not by the first query that touches it. Tables are matched in the current schema,
-- the tenant schema this chain runs in, to which the schema qualifiers below are
-- rewritten at execution, as in every generated migration of the chains.
DO $governance_channel$
DECLARE
  v_tables CONSTANT text[] := ARRAY[
      'channel_approvals',
      'channel_audit',
      'channel_discussions',
      'channel_jobs',
      'channel_members',
      'channel_messages',
      'channel_outbox',
      'channel_runs',
      'channel_runtime_messages',
      'channel_runtime_states',
      'channel_sessions',
      'channel_threads',
      'channels',
      'command_execution_logs',
      'command_governance_rules',
      'user_execution_policies'
  ];
  v_present integer;
  v_differs text;
BEGIN
  SELECT count(*) INTO v_present FROM unnest(v_tables) AS t(name)
   WHERE to_regclass(format('%I.%I', current_schema(), t.name)) IS NOT NULL;
  IF v_present = 0 THEN
    CREATE TABLE "channel_approvals" (
    	"id" text PRIMARY KEY NOT NULL,
    	"run_id" text NOT NULL,
    	"request" jsonb NOT NULL,
    	"decision" text,
    	"expires_at" timestamp with time zone NOT NULL,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL
    );
    CREATE TABLE "channel_audit" (
    	"id" text PRIMARY KEY NOT NULL,
    	"channel_id" text NOT NULL,
    	"event" text NOT NULL,
    	"target_id" text NOT NULL,
    	"details" jsonb DEFAULT '{}'::jsonb NOT NULL,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL
    );
    CREATE TABLE "channel_discussions" (
    	"id" text PRIMARY KEY NOT NULL,
    	"channel_id" text NOT NULL,
    	"request_message_id" text NOT NULL,
    	"thread_id" text,
    	"participant_ids" jsonb NOT NULL,
    	"max_rounds" integer NOT NULL,
    	"round" integer DEFAULT 1 NOT NULL,
    	"turns_published" integer DEFAULT 0 NOT NULL,
    	"status" text DEFAULT 'active' NOT NULL,
    	"end_reason" text,
    	"summary_message_id" text,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL
    );
    CREATE TABLE "channel_jobs" (
    	"id" text PRIMARY KEY NOT NULL,
    	"channel_id" text NOT NULL,
    	"member_id" text NOT NULL,
    	"message_id" text NOT NULL,
    	"thread_id" text,
    	"discussion_id" text,
    	"task" jsonb,
    	"delivery_key" text DEFAULT 'initial' NOT NULL,
    	"status" text DEFAULT 'queued' NOT NULL,
    	"blocked_reason" text,
    	"blocked_code" text,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
    	CONSTRAINT "channel_jobs_scope_idx" UNIQUE("channel_id","id")
    );
    CREATE TABLE "channel_members" (
    	"id" text PRIMARY KEY NOT NULL,
    	"channel_id" text NOT NULL,
    	"name" text NOT NULL,
    	"description" text DEFAULT '' NOT NULL,
    	"config" jsonb NOT NULL,
    	"active" boolean DEFAULT true NOT NULL,
    	"execution_paused" boolean DEFAULT false NOT NULL,
    	"environment_revision" integer DEFAULT 0 NOT NULL,
    	"environment_cutoff" integer DEFAULT 0 NOT NULL,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
    	CONSTRAINT "channel_members_scope_idx" UNIQUE("channel_id","id")
    );
    CREATE TABLE "channel_messages" (
    	"id" text PRIMARY KEY NOT NULL,
    	"channel_id" text NOT NULL,
    	"thread_id" text,
    	"sequence" integer NOT NULL,
    	"author_member_id" text,
    	"content" text NOT NULL,
    	"file_ids" jsonb DEFAULT '[]'::jsonb NOT NULL,
    	"mentions" jsonb DEFAULT '[]'::jsonb NOT NULL,
    	"request_key" text NOT NULL,
    	"reply_to_id" text,
    	"routing_status" text NOT NULL,
    	"routing_reason" text,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
    	CONSTRAINT "channel_messages_scope_idx" UNIQUE("channel_id","id")
    );
    CREATE TABLE "channel_outbox" (
    	"id" text PRIMARY KEY NOT NULL,
    	"channel_id" text NOT NULL,
    	"kind" text NOT NULL,
    	"target_id" text NOT NULL,
    	"processed" boolean DEFAULT false NOT NULL,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL
    );
    CREATE TABLE "channel_runs" (
    	"id" text PRIMARY KEY NOT NULL,
    	"channel_id" text NOT NULL,
    	"job_id" text NOT NULL,
    	"member_id" text NOT NULL,
    	"session_id" text NOT NULL,
    	"status" text DEFAULT 'starting' NOT NULL,
    	"activity" text,
    	"fence" integer DEFAULT 1 NOT NULL,
    	"execution_fence" integer DEFAULT 1 NOT NULL,
    	"execution_config" jsonb,
    	"environment_revision" integer DEFAULT 0 NOT NULL,
    	"physical_stopped" boolean DEFAULT false NOT NULL,
    	"cleanup_requested" boolean DEFAULT false NOT NULL,
    	"environment_error" text,
    	"manifest" jsonb NOT NULL,
    	"acceptance" text DEFAULT 'pending' NOT NULL,
    	"native_turn_id" text,
    	"publication_revoked" boolean DEFAULT false NOT NULL,
    	"writer_released" boolean DEFAULT false NOT NULL,
    	"draft" text,
    	"publication_status" text DEFAULT 'pending' NOT NULL,
    	"published_message_id" text,
    	"error" text,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL
    );
    CREATE TABLE "channel_runtime_messages" (
    	"id" text PRIMARY KEY NOT NULL,
    	"session_id" text NOT NULL,
    	"run_id" text NOT NULL,
    	"stable_key" text NOT NULL,
    	"data" jsonb NOT NULL,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL
    );
    CREATE TABLE "channel_runtime_states" (
    	"session_id" text PRIMARY KEY NOT NULL,
    	"run_id" text NOT NULL,
    	"state" jsonb NOT NULL
    );
    CREATE TABLE "channel_sessions" (
    	"id" text PRIMARY KEY NOT NULL,
    	"channel_id" text NOT NULL,
    	"member_id" text NOT NULL,
    	"scope" text NOT NULL,
    	"generation" integer DEFAULT 1 NOT NULL,
    	"native_session_id" text,
    	"accepted_message_ids" jsonb DEFAULT '[]'::jsonb NOT NULL,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL
    );
    CREATE TABLE "channel_threads" (
    	"id" text PRIMARY KEY NOT NULL,
    	"channel_id" text NOT NULL,
    	"root_message_id" text NOT NULL,
    	"root_sequence" integer NOT NULL,
    	"follower_member_ids" jsonb DEFAULT '[]'::jsonb NOT NULL,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
    	CONSTRAINT "channel_threads_scope_idx" UNIQUE("channel_id","id")
    );
    CREATE TABLE "channels" (
    	"id" text PRIMARY KEY NOT NULL,
    	"owner_id" text NOT NULL,
    	"title" text NOT NULL,
    	"sequence" integer DEFAULT 0 NOT NULL,
    	"revision" integer DEFAULT 0 NOT NULL,
    	"archived" boolean DEFAULT false NOT NULL,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL
    );
    CREATE TABLE "command_execution_logs" (
    	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
    	"user_id" text NOT NULL,
    	"execution_target" text NOT NULL,
    	"device_id" text,
    	"tool_identifier" text NOT NULL,
    	"api_name" text NOT NULL,
    	"command_text" text,
    	"blocked" boolean NOT NULL,
    	"matched_rule_id" uuid,
    	"path" text,
    	"policy_field" text,
    	"success" boolean,
    	"error_message" text,
    	"duration_ms" integer,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL
    );
    CREATE TABLE "command_governance_rules" (
    	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
    	"user_id" text NOT NULL,
    	"pattern" text NOT NULL,
    	"pattern_type" text NOT NULL,
    	"scope" text DEFAULT 'all' NOT NULL,
    	"action" text DEFAULT 'deny' NOT NULL,
    	"enabled" boolean DEFAULT true NOT NULL,
    	"created_by" text,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
    	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
    );
    CREATE TABLE "user_execution_policies" (
    	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
    	"user_id" text NOT NULL,
    	"enabled" boolean DEFAULT true NOT NULL,
    	"writable_roots" jsonb DEFAULT '[]'::jsonb NOT NULL,
    	"readable_roots" jsonb,
    	"denied_write_roots" jsonb,
    	"denied_read_roots" jsonb,
    	"allow_network" boolean DEFAULT false NOT NULL,
    	"allowed_network_domains" jsonb,
    	"env_allowlist" jsonb,
    	"command_mode" text DEFAULT 'sandbox' NOT NULL,
    	"created_by" text,
    	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
    	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
    	CONSTRAINT "user_execution_policies_user_id_unique" UNIQUE("user_id")
    );
    ALTER TABLE "channel_approvals" ADD CONSTRAINT "channel_approvals_run_id_channel_runs_id_fk" FOREIGN KEY ("run_id") REFERENCES "public"."channel_runs"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_audit" ADD CONSTRAINT "channel_audit_channel_id_channels_id_fk" FOREIGN KEY ("channel_id") REFERENCES "public"."channels"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_discussions" ADD CONSTRAINT "channel_discussions_channel_id_channels_id_fk" FOREIGN KEY ("channel_id") REFERENCES "public"."channels"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_discussions" ADD CONSTRAINT "channel_discussions_request_message_id_channel_messages_id_fk" FOREIGN KEY ("request_message_id") REFERENCES "public"."channel_messages"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_jobs" ADD CONSTRAINT "channel_jobs_channel_id_channels_id_fk" FOREIGN KEY ("channel_id") REFERENCES "public"."channels"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_jobs" ADD CONSTRAINT "channel_jobs_discussion_id_channel_discussions_id_fk" FOREIGN KEY ("discussion_id") REFERENCES "public"."channel_discussions"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_jobs" ADD CONSTRAINT "channel_jobs_member_fk" FOREIGN KEY ("channel_id","member_id") REFERENCES "public"."channel_members"("channel_id","id") ON DELETE no action ON UPDATE no action;
    ALTER TABLE "channel_jobs" ADD CONSTRAINT "channel_jobs_message_fk" FOREIGN KEY ("channel_id","message_id") REFERENCES "public"."channel_messages"("channel_id","id") ON DELETE no action ON UPDATE no action;
    ALTER TABLE "channel_jobs" ADD CONSTRAINT "channel_jobs_thread_fk" FOREIGN KEY ("channel_id","thread_id") REFERENCES "public"."channel_threads"("channel_id","id") ON DELETE no action ON UPDATE no action;
    ALTER TABLE "channel_members" ADD CONSTRAINT "channel_members_channel_id_channels_id_fk" FOREIGN KEY ("channel_id") REFERENCES "public"."channels"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_messages" ADD CONSTRAINT "channel_messages_channel_id_channels_id_fk" FOREIGN KEY ("channel_id") REFERENCES "public"."channels"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_messages" ADD CONSTRAINT "channel_messages_thread_fk" FOREIGN KEY ("channel_id","thread_id") REFERENCES "public"."channel_threads"("channel_id","id") ON DELETE no action ON UPDATE no action;
    ALTER TABLE "channel_messages" ADD CONSTRAINT "channel_messages_author_fk" FOREIGN KEY ("channel_id","author_member_id") REFERENCES "public"."channel_members"("channel_id","id") ON DELETE no action ON UPDATE no action;
    ALTER TABLE "channel_outbox" ADD CONSTRAINT "channel_outbox_channel_id_channels_id_fk" FOREIGN KEY ("channel_id") REFERENCES "public"."channels"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_runs" ADD CONSTRAINT "channel_runs_channel_id_channels_id_fk" FOREIGN KEY ("channel_id") REFERENCES "public"."channels"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_runs" ADD CONSTRAINT "channel_runs_session_id_channel_sessions_id_fk" FOREIGN KEY ("session_id") REFERENCES "public"."channel_sessions"("id") ON DELETE no action ON UPDATE no action;
    ALTER TABLE "channel_runs" ADD CONSTRAINT "channel_runs_job_fk" FOREIGN KEY ("channel_id","job_id") REFERENCES "public"."channel_jobs"("channel_id","id") ON DELETE no action ON UPDATE no action;
    ALTER TABLE "channel_runs" ADD CONSTRAINT "channel_runs_member_fk" FOREIGN KEY ("channel_id","member_id") REFERENCES "public"."channel_members"("channel_id","id") ON DELETE no action ON UPDATE no action;
    ALTER TABLE "channel_runtime_messages" ADD CONSTRAINT "channel_runtime_messages_session_id_channel_sessions_id_fk" FOREIGN KEY ("session_id") REFERENCES "public"."channel_sessions"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_runtime_messages" ADD CONSTRAINT "channel_runtime_messages_run_id_channel_runs_id_fk" FOREIGN KEY ("run_id") REFERENCES "public"."channel_runs"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_runtime_states" ADD CONSTRAINT "channel_runtime_states_session_id_channel_sessions_id_fk" FOREIGN KEY ("session_id") REFERENCES "public"."channel_sessions"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_runtime_states" ADD CONSTRAINT "channel_runtime_states_run_id_channel_runs_id_fk" FOREIGN KEY ("run_id") REFERENCES "public"."channel_runs"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_sessions" ADD CONSTRAINT "channel_sessions_channel_id_channels_id_fk" FOREIGN KEY ("channel_id") REFERENCES "public"."channels"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_sessions" ADD CONSTRAINT "channel_sessions_member_fk" FOREIGN KEY ("channel_id","member_id") REFERENCES "public"."channel_members"("channel_id","id") ON DELETE no action ON UPDATE no action;
    ALTER TABLE "channel_threads" ADD CONSTRAINT "channel_threads_channel_id_channels_id_fk" FOREIGN KEY ("channel_id") REFERENCES "public"."channels"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channel_threads" ADD CONSTRAINT "channel_threads_root_fk" FOREIGN KEY ("channel_id","root_message_id") REFERENCES "public"."channel_messages"("channel_id","id") ON DELETE no action ON UPDATE no action;
    ALTER TABLE "command_execution_logs" ADD CONSTRAINT "command_execution_logs_matched_rule_id_command_governance_rules_id_fk" FOREIGN KEY ("matched_rule_id") REFERENCES "public"."command_governance_rules"("id") ON DELETE set null ON UPDATE no action;
    CREATE INDEX "channel_approvals_run_idx" ON "channel_approvals" USING btree ("run_id");
    CREATE INDEX "channel_audit_channel_event_idx" ON "channel_audit" USING btree ("channel_id","event","created_at");
    CREATE INDEX "channel_audit_target_event_idx" ON "channel_audit" USING btree ("target_id","event","created_at");
    CREATE INDEX "channel_discussions_channel_status_idx" ON "channel_discussions" USING btree ("channel_id","status");
    CREATE INDEX "channel_discussions_request_idx" ON "channel_discussions" USING btree ("request_message_id");
    CREATE UNIQUE INDEX "channel_jobs_delivery_idx" ON "channel_jobs" USING btree ("message_id","member_id","delivery_key");
    CREATE INDEX "channel_jobs_queue_idx" ON "channel_jobs" USING btree ("status","created_at");
    CREATE INDEX "channel_jobs_channel_status_idx" ON "channel_jobs" USING btree ("channel_id","status");
    CREATE UNIQUE INDEX "channel_messages_seq_idx" ON "channel_messages" USING btree ("channel_id","sequence");
    CREATE INDEX "channel_messages_thread_sequence_idx" ON "channel_messages" USING btree ("channel_id","thread_id","sequence");
    CREATE INDEX "channel_messages_request_sequence_idx" ON "channel_messages" USING btree ("channel_id","thread_id","sequence") WHERE "channel_messages"."author_member_id" IS NULL;
    CREATE INDEX "channel_messages_routing_pending_idx" ON "channel_messages" USING btree ("channel_id","id") WHERE "channel_messages"."routing_status" = 'pending';
    CREATE UNIQUE INDEX "channel_messages_request_idx" ON "channel_messages" USING btree ("channel_id","request_key");
    CREATE INDEX "channel_outbox_pending_idx" ON "channel_outbox" USING btree ("processed","created_at");
    CREATE UNIQUE INDEX "channel_runs_job_idx" ON "channel_runs" USING btree ("job_id");
    CREATE INDEX "channel_runs_channel_idx" ON "channel_runs" USING btree ("channel_id");
    CREATE INDEX "channel_runs_unsettled_idx" ON "channel_runs" USING btree ("channel_id","id") WHERE "channel_runs"."writer_released" = false OR "channel_runs"."physical_stopped" = false;
    CREATE UNIQUE INDEX "channel_runs_active_member_idx" ON "channel_runs" USING btree ("member_id") WHERE "channel_runs"."writer_released" = false;
    CREATE UNIQUE INDEX "channel_runtime_messages_key_idx" ON "channel_runtime_messages" USING btree ("session_id","stable_key");
    CREATE UNIQUE INDEX "channel_sessions_member_scope_idx" ON "channel_sessions" USING btree ("member_id","scope");
    CREATE UNIQUE INDEX "channel_threads_root_idx" ON "channel_threads" USING btree ("channel_id","root_message_id");
    CREATE INDEX "channels_owner_idx" ON "channels" USING btree ("owner_id");
    CREATE INDEX "command_execution_logs_user_id_idx" ON "command_execution_logs" USING btree ("user_id");
    CREATE INDEX "command_execution_logs_created_at_idx" ON "command_execution_logs" USING btree ("created_at");
    CREATE INDEX "command_execution_logs_execution_target_idx" ON "command_execution_logs" USING btree ("execution_target");
    CREATE INDEX "command_execution_logs_blocked_idx" ON "command_execution_logs" USING btree ("blocked");
    CREATE INDEX "command_governance_rules_user_id_idx" ON "command_governance_rules" USING btree ("user_id");
    CREATE INDEX "command_governance_rules_user_id_enabled_idx" ON "command_governance_rules" USING btree ("user_id","enabled");
    ALTER TABLE "command_execution_logs" ADD CONSTRAINT "command_execution_logs_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "command_governance_rules" ADD CONSTRAINT "command_governance_rules_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "user_execution_policies" ADD CONSTRAINT "user_execution_policies_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
    ALTER TABLE "channels" ADD CONSTRAINT "channels_owner_id_users_id_fk" FOREIGN KEY ("owner_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
CREATE FUNCTION "public"."channel_bump_revision"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN
    RETURN NULL;
  END IF;
  UPDATE "public"."channels" SET "revision" = "revision" + 1
  WHERE "id" = CASE WHEN TG_OP = 'DELETE' THEN OLD."channel_id" ELSE NEW."channel_id" END;
  RETURN NULL;
END;
$$;
CREATE FUNCTION "public"."channel_self_revision"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."revision" = OLD."revision" AND NEW IS DISTINCT FROM OLD THEN
    NEW."revision" := OLD."revision" + 1;
  END IF;
  RETURN NEW;
END;
$$;
    CREATE TRIGGER "channels_revision" BEFORE UPDATE ON "channels"
      FOR EACH ROW EXECUTE FUNCTION "public"."channel_self_revision"();
    CREATE TRIGGER "channel_members_revision" AFTER INSERT OR UPDATE OR DELETE ON "channel_members"
      FOR EACH ROW EXECUTE FUNCTION "public"."channel_bump_revision"();
    CREATE TRIGGER "channel_threads_revision" AFTER INSERT OR UPDATE OR DELETE ON "channel_threads"
      FOR EACH ROW EXECUTE FUNCTION "public"."channel_bump_revision"();
    CREATE TRIGGER "channel_messages_revision" AFTER INSERT OR UPDATE OR DELETE ON "channel_messages"
      FOR EACH ROW EXECUTE FUNCTION "public"."channel_bump_revision"();
    CREATE TRIGGER "channel_jobs_revision" AFTER INSERT OR UPDATE OR DELETE ON "channel_jobs"
      FOR EACH ROW EXECUTE FUNCTION "public"."channel_bump_revision"();
    CREATE TRIGGER "channel_runs_revision" AFTER INSERT OR UPDATE OR DELETE ON "channel_runs"
      FOR EACH ROW EXECUTE FUNCTION "public"."channel_bump_revision"();
    CREATE TRIGGER "channel_discussions_revision" AFTER INSERT OR UPDATE OR DELETE ON "channel_discussions"
      FOR EACH ROW EXECUTE FUNCTION "public"."channel_bump_revision"();
  ELSIF v_present <> cardinality(v_tables) THEN
    RAISE EXCEPTION 'governance and Channel tables are only partly present in schema %', current_schema();
  END IF;

  SELECT string_agg(e.name, ', ' ORDER BY e.name) INTO v_differs
    FROM (VALUES
      ('channel_approvals',
       'created_at:timestamp with time zone:n:now(),decision:text:y:,expires_at:timestamp with time zone:n:,id:text:n:,request:jsonb:n:,run_id:text:n:',
       'c:channel_approvals_pkey:p,c:channel_approvals_run_id_channel_runs_id_fk:f,i:channel_approvals_pkey,i:channel_approvals_run_idx'),
      ('channel_audit',
       'channel_id:text:n:,created_at:timestamp with time zone:n:now(),details:jsonb:n:''{}''::jsonb,event:text:n:,id:text:n:,target_id:text:n:',
       'c:channel_audit_channel_id_channels_id_fk:f,c:channel_audit_pkey:p,i:channel_audit_channel_event_idx,i:channel_audit_pkey,i:channel_audit_target_event_idx'),
      ('channel_discussions',
       'channel_id:text:n:,created_at:timestamp with time zone:n:now(),end_reason:text:y:,id:text:n:,max_rounds:integer:n:,participant_ids:jsonb:n:,request_message_id:text:n:,round:integer:n:1,status:text:n:''active''::text,summary_message_id:text:y:,thread_id:text:y:,turns_published:integer:n:0',
       'c:channel_discussions_channel_id_channels_id_fk:f,c:channel_discussions_pkey:p,c:channel_discussions_request_message_id_channel_messages_id_fk:f,i:channel_discussions_channel_status_idx,i:channel_discussions_pkey,i:channel_discussions_request_idx,t:channel_discussions_revision'),
      ('channel_jobs',
       'blocked_code:text:y:,blocked_reason:text:y:,channel_id:text:n:,created_at:timestamp with time zone:n:now(),delivery_key:text:n:''initial''::text,discussion_id:text:y:,id:text:n:,member_id:text:n:,message_id:text:n:,status:text:n:''queued''::text,task:jsonb:y:,thread_id:text:y:',
       'c:channel_jobs_channel_id_channels_id_fk:f,c:channel_jobs_discussion_id_channel_discussions_id_fk:f,c:channel_jobs_member_fk:f,c:channel_jobs_message_fk:f,c:channel_jobs_pkey:p,c:channel_jobs_scope_idx:u,c:channel_jobs_thread_fk:f,i:channel_jobs_channel_status_idx,i:channel_jobs_delivery_idx,i:channel_jobs_pkey,i:channel_jobs_queue_idx,i:channel_jobs_scope_idx,t:channel_jobs_revision'),
      ('channel_members',
       'active:boolean:n:true,channel_id:text:n:,config:jsonb:n:,created_at:timestamp with time zone:n:now(),description:text:n:''''::text,environment_cutoff:integer:n:0,environment_revision:integer:n:0,execution_paused:boolean:n:false,id:text:n:,name:text:n:',
       'c:channel_members_channel_id_channels_id_fk:f,c:channel_members_pkey:p,c:channel_members_scope_idx:u,i:channel_members_pkey,i:channel_members_scope_idx,t:channel_members_revision'),
      ('channel_messages',
       'author_member_id:text:y:,channel_id:text:n:,content:text:n:,created_at:timestamp with time zone:n:now(),file_ids:jsonb:n:''[]''::jsonb,id:text:n:,mentions:jsonb:n:''[]''::jsonb,reply_to_id:text:y:,request_key:text:n:,routing_reason:text:y:,routing_status:text:n:,sequence:integer:n:,thread_id:text:y:',
       'c:channel_messages_author_fk:f,c:channel_messages_channel_id_channels_id_fk:f,c:channel_messages_pkey:p,c:channel_messages_scope_idx:u,c:channel_messages_thread_fk:f,i:channel_messages_pkey,i:channel_messages_request_idx,i:channel_messages_request_sequence_idx,i:channel_messages_routing_pending_idx,i:channel_messages_scope_idx,i:channel_messages_seq_idx,i:channel_messages_thread_sequence_idx,t:channel_messages_revision'),
      ('channel_outbox',
       'channel_id:text:n:,created_at:timestamp with time zone:n:now(),id:text:n:,kind:text:n:,processed:boolean:n:false,target_id:text:n:',
       'c:channel_outbox_channel_id_channels_id_fk:f,c:channel_outbox_pkey:p,i:channel_outbox_pending_idx,i:channel_outbox_pkey'),
      ('channel_runs',
       'acceptance:text:n:''pending''::text,activity:text:y:,channel_id:text:n:,cleanup_requested:boolean:n:false,created_at:timestamp with time zone:n:now(),draft:text:y:,environment_error:text:y:,environment_revision:integer:n:0,error:text:y:,execution_config:jsonb:y:,execution_fence:integer:n:1,fence:integer:n:1,id:text:n:,job_id:text:n:,manifest:jsonb:n:,member_id:text:n:,native_turn_id:text:y:,physical_stopped:boolean:n:false,publication_revoked:boolean:n:false,publication_status:text:n:''pending''::text,published_message_id:text:y:,session_id:text:n:,status:text:n:''starting''::text,writer_released:boolean:n:false',
       'c:channel_runs_channel_id_channels_id_fk:f,c:channel_runs_job_fk:f,c:channel_runs_member_fk:f,c:channel_runs_pkey:p,c:channel_runs_session_id_channel_sessions_id_fk:f,i:channel_runs_active_member_idx,i:channel_runs_channel_idx,i:channel_runs_job_idx,i:channel_runs_pkey,i:channel_runs_unsettled_idx,t:channel_runs_revision'),
      ('channel_runtime_messages',
       'created_at:timestamp with time zone:n:now(),data:jsonb:n:,id:text:n:,run_id:text:n:,session_id:text:n:,stable_key:text:n:',
       'c:channel_runtime_messages_pkey:p,c:channel_runtime_messages_run_id_channel_runs_id_fk:f,c:channel_runtime_messages_session_id_channel_sessions_id_fk:f,i:channel_runtime_messages_key_idx,i:channel_runtime_messages_pkey'),
      ('channel_runtime_states',
       'run_id:text:n:,session_id:text:n:,state:jsonb:n:',
       'c:channel_runtime_states_pkey:p,c:channel_runtime_states_run_id_channel_runs_id_fk:f,c:channel_runtime_states_session_id_channel_sessions_id_fk:f,i:channel_runtime_states_pkey'),
      ('channel_sessions',
       'accepted_message_ids:jsonb:n:''[]''::jsonb,channel_id:text:n:,created_at:timestamp with time zone:n:now(),generation:integer:n:1,id:text:n:,member_id:text:n:,native_session_id:text:y:,scope:text:n:',
       'c:channel_sessions_channel_id_channels_id_fk:f,c:channel_sessions_member_fk:f,c:channel_sessions_pkey:p,i:channel_sessions_member_scope_idx,i:channel_sessions_pkey'),
      ('channel_threads',
       'channel_id:text:n:,created_at:timestamp with time zone:n:now(),follower_member_ids:jsonb:n:''[]''::jsonb,id:text:n:,root_message_id:text:n:,root_sequence:integer:n:',
       'c:channel_threads_channel_id_channels_id_fk:f,c:channel_threads_pkey:p,c:channel_threads_root_fk:f,c:channel_threads_scope_idx:u,i:channel_threads_pkey,i:channel_threads_root_idx,i:channel_threads_scope_idx,t:channel_threads_revision'),
      ('channels',
       'archived:boolean:n:false,created_at:timestamp with time zone:n:now(),id:text:n:,owner_id:text:n:,revision:integer:n:0,sequence:integer:n:0,title:text:n:',
       'c:channels_owner_id_users_id_fk:f,c:channels_pkey:p,i:channels_owner_idx,i:channels_pkey,t:channels_revision'),
      ('command_execution_logs',
       'api_name:text:n:,blocked:boolean:n:,command_text:text:y:,created_at:timestamp with time zone:n:now(),device_id:text:y:,duration_ms:integer:y:,error_message:text:y:,execution_target:text:n:,id:uuid:n:gen_random_uuid(),matched_rule_id:uuid:y:,path:text:y:,policy_field:text:y:,success:boolean:y:,tool_identifier:text:n:,user_id:text:n:',
       'c:command_execution_logs_matched_rule_id_command_governance_rules:f,c:command_execution_logs_pkey:p,c:command_execution_logs_user_id_users_id_fk:f,i:command_execution_logs_blocked_idx,i:command_execution_logs_created_at_idx,i:command_execution_logs_execution_target_idx,i:command_execution_logs_pkey,i:command_execution_logs_user_id_idx'),
      ('command_governance_rules',
       'action:text:n:''deny''::text,created_at:timestamp with time zone:n:now(),created_by:text:y:,enabled:boolean:n:true,id:uuid:n:gen_random_uuid(),pattern:text:n:,pattern_type:text:n:,scope:text:n:''all''::text,updated_at:timestamp with time zone:n:now(),user_id:text:n:',
       'c:command_governance_rules_pkey:p,c:command_governance_rules_user_id_users_id_fk:f,i:command_governance_rules_pkey,i:command_governance_rules_user_id_enabled_idx,i:command_governance_rules_user_id_idx'),
      ('user_execution_policies',
       'allow_network:boolean:n:false,allowed_network_domains:jsonb:y:,command_mode:text:n:''sandbox''::text,created_at:timestamp with time zone:n:now(),created_by:text:y:,denied_read_roots:jsonb:y:,denied_write_roots:jsonb:y:,enabled:boolean:n:true,env_allowlist:jsonb:y:,id:uuid:n:gen_random_uuid(),readable_roots:jsonb:y:,updated_at:timestamp with time zone:n:now(),user_id:text:n:,writable_roots:jsonb:n:''[]''::jsonb',
       'c:user_execution_policies_pkey:p,c:user_execution_policies_user_id_unique:u,c:user_execution_policies_user_id_users_id_fk:f,i:user_execution_policies_pkey,i:user_execution_policies_user_id_unique')
    ) AS e(name, columns, objects)
    LEFT JOIN LATERAL (
      SELECT string_agg(
               a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':'
                 || CASE WHEN a.attnotnull THEN 'n' ELSE 'y' END || ':'
                 || COALESCE(pg_get_expr(d.adbin, d.adrelid), ''),
               ',' ORDER BY a.attname COLLATE "C") AS columns
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped
        LEFT JOIN pg_attrdef d ON d.adrelid = c.oid AND d.adnum = a.attnum
       WHERE n.nspname = current_schema() AND c.relkind = 'r' AND c.relname = e.name
    ) actual_columns ON true
    LEFT JOIN LATERAL (
      SELECT string_agg(o.name, ',' ORDER BY o.name COLLATE "C") AS objects
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        JOIN (
          SELECT conrelid AS rel, 'c:' || conname || ':' || contype::text AS name
            FROM pg_constraint WHERE contype IN ('p', 'u', 'f', 'c')
          UNION ALL
          SELECT indrelid, 'i:' || ic.relname FROM pg_index JOIN pg_class ic ON ic.oid = indexrelid
          UNION ALL
          SELECT tgrelid, 't:' || tgname FROM pg_trigger WHERE NOT tgisinternal
        ) o ON o.rel = c.oid
       WHERE n.nspname = current_schema() AND c.relkind = 'r' AND c.relname = e.name
    ) actual_objects ON true
   WHERE actual_columns.columns IS DISTINCT FROM e.columns
      OR actual_objects.objects IS DISTINCT FROM e.objects;
  IF v_differs IS NOT NULL THEN
    RAISE EXCEPTION 'governance and Channel tables differ from the tenant chain definition in schema %: %',
      current_schema(), v_differs;
  END IF;

  SELECT string_agg(f.name, ', ' ORDER BY f.name) INTO v_differs
    FROM (VALUES
      ('channel_bump_revision', '39e31ebec52ce5dc49c24f2ef17c5acc'),
      ('channel_self_revision', 'b23b4290e8f41f48967d0732b67735b1')
    ) AS f(name, digest)
    LEFT JOIN pg_proc p ON p.proname = f.name
      AND p.pronamespace = to_regnamespace(quote_ident(current_schema()))
   WHERE md5(replace(p.prosrc, '"' || current_schema() || '".', '')) IS DISTINCT FROM f.digest;
  IF v_differs IS NOT NULL THEN
    RAISE EXCEPTION 'Channel revision functions differ from the tenant chain definition in schema %: %',
      current_schema(), v_differs;
  END IF;
END
$governance_channel$;
